@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=Rajdhani:wght@400;500;600;700&display=swap');
:root{--acid:#d4e34d;--white:#e9e9e3;--muted:#879092;--red:#ed4a38}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101316;color:var(--white);font-family:'Rajdhani',sans-serif}#game-shell{position:relative;width:100%;height:100%;min-height:320px;overflow:hidden;background:#121518}#game{display:block;width:100%;height:100%;image-rendering:pixelated}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 35%,rgba(0,0,0,.33) 100%),linear-gradient(180deg,rgba(8,10,12,.54),transparent 25%,transparent 66%,rgba(8,10,12,.48)}.topline{position:absolute;z-index:2;top:0;left:0;right:0;height:76px;padding:17px 30px;display:flex;align-items:center;gap:20px;background:linear-gradient(180deg,rgba(9,12,14,.86),transparent)}.brand{display:flex;align-items:center;gap:10px;font:800 19px 'Barlow Condensed',sans-serif;letter-spacing:1.6px}.brand small{display:block;font:600 9px 'Rajdhani';letter-spacing:3px;color:#a6acad;margin-top:1px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid var(--acid);color:var(--acid);font:800 14px 'Barlow Condensed';transform:skew(-7deg)}.objective{margin:auto;font:700 12px 'Rajdhani';letter-spacing:2px;color:#d4d7d2}.objective i,.player-tag span,.overline span{display:inline-block;width:6px;height:6px;background:var(--acid);border-radius:50%;margin-right:8px;box-shadow:0 0 12px var(--acid)}.icon-btn{border:1px solid #6c7470;background:#111719aa;color:var(--acid);height:34px;width:34px;font-size:17px;cursor:pointer}.hud{position:absolute;top:82px;left:30px;display:flex;align-items:stretch;gap:24px;padding:12px 15px;background:linear-gradient(90deg,rgba(7,11,13,.83),rgba(7,11,13,.38));border-left:2px solid var(--acid);clip-path:polygon(0 0,100% 0,100% 100%,8px 100%,0 calc(100% - 8px));min-width:500px}.eyebrow{display:block;color:#aab1ae;font:700 9px 'Rajdhani';letter-spacing:2px}.wave-card{display:grid;grid-template-columns:42px 1fr;grid-template-rows:14px 15px;column-gap:4px;min-width:110px}.wave-card .eyebrow{grid-column:1/3}.wave-card strong{grid-row:2;font:700 24px/.8 'Barlow Condensed';color:var(--acid)}.wave-card>span:last-child{align-self:center;font-size:10px;letter-spacing:1px;color:#d1d6cf}.mission{min-width:125px;border-left:1px solid #58605c;padding-left:17px}.mission strong{font:700 18px 'Barlow Condensed';margin-right:8px}.progress{display:inline-block;width:55px;height:3px;vertical-align:middle;background:#3c4341}.progress i{display:block;width:0;height:100%;background:var(--acid)}.health{border-left:1px solid #58605c;padding-left:17px;min-width:95px}.health-line{display:inline-block;width:64px;height:5px;background:#3c413f;vertical-align:middle;margin:7px 5px 0 0}.health-line i{display:block;width:100%;height:100%;background:var(--acid)}.health strong{font:700 15px 'Barlow Condensed'}.ammo{border-left:1px solid #58605c;padding-left:17px;min-width:124px}.ammo strong{display:block;font:700 26px/.9 'Barlow Condensed';color:var(--acid);margin-top:4px}.ammo strong small{font-size:15px;color:#e3e5e0}.ammo>span:last-child{font-size:9px;letter-spacing:1px;color:#b1b8b2}.bottom-hud{position:absolute;bottom:18px;left:27px;right:27px;display:flex;justify-content:space-between;align-items:flex-end;text-shadow:0 1px 5px #000}.controls-hint{font:700 10px 'Rajdhani';letter-spacing:1.1px;color:#c3c8c3}.controls-hint kbd{font:700 10px 'Rajdhani';border:1px solid #777c77;padding:2px 5px;color:#eee;margin:0 4px 0 10px;background:#1118}.player-tag{font:700 12px 'Rajdhani';letter-spacing:1.5px}.player-tag small{display:block;text-align:right;font-size:9px;color:#a1a7a4;letter-spacing:2px}.player-tag span{margin-right:7px}#crosshair{position:absolute;left:50%;top:50%;width:24px;height:24px;transform:translate(-50%,-50%);pointer-events:none;filter:drop-shadow(0 1px 2px #111)}#crosshair i{position:absolute;background:rgba(235,240,222,.92);display:block}#crosshair i:nth-child(1){width:2px;height:6px;left:11px;top:0}#crosshair i:nth-child(2){width:2px;height:6px;left:11px;bottom:0}#crosshair i:nth-child(3){width:6px;height:2px;left:0;top:11px}#crosshair i:nth-child(4){width:6px;height:2px;right:0;top:11px}#crosshair b{position:absolute;width:3px;height:3px;background:var(--acid);left:10px;top:10px;border-radius:50%}#hitmarker{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) scale(.6);font:24px sans-serif;color:var(--acid);opacity:0;pointer-events:none}#damage-flash{position:absolute;inset:0;pointer-events:none;opacity:0;background:radial-gradient(ellipse,transparent 42%,rgba(170,20,16,.68))}.toast{position:absolute;top:27%;left:50%;transform:translate(-50%,-10px);opacity:0;text-align:center;padding:8px 15px;background:#101514d9;border:1px solid #727a70;color:var(--acid);font:700 12px 'Rajdhani';letter-spacing:2px;transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.interaction{position:absolute;bottom:19%;left:50%;transform:translateX(-50%);display:none;background:#101514dd;padding:8px 15px;color:var(--acid);font-weight:700;letter-spacing:1px}.interaction span{color:white;font-size:12px}#map-wrap{position:absolute;right:26px;top:82px;width:145px;background:#0b0f10b8;padding:8px;border-top:1px solid #777d72}.map-label{font:700 9px 'Rajdhani';letter-spacing:2px;color:#acb2ae;margin:0 0 5px}.map-label b{color:var(--acid)}#minimap{width:100%;height:auto;display:block;opacity:.85}.overlay{position:absolute;z-index:5;inset:0;display:grid;place-items:center;background:rgba(5,8,10,.53);backdrop-filter:blur(3px);transition:opacity .3s}.overlay.hidden{opacity:0;pointer-events:none}.modal{width:min(440px,calc(100% - 36px));padding:25px 42px 24px;text-align:center;background:linear-gradient(145deg,rgba(27,32,31,.97),rgba(12,16,17,.97));border:1px solid #606762;box-shadow:0 22px 80px #0009;position:relative}.modal:before,.modal:after{content:'';position:absolute;width:18px;height:18px;border-color:var(--acid);border-style:solid}.modal:before{left:-1px;top:-1px;border-width:2px 0 0 2px}.modal:after{right:-1px;bottom:-1px;border-width:0 2px 2px 0}.overline{font:700 10px 'Rajdhani';letter-spacing:3px;color:#b9c0ba}.overline span{width:4px;height:4px;margin:0 9px 2px}.crest{margin:18px auto 8px;width:48px;height:48px;display:grid;place-items:center;border:1px solid var(--acid);transform:rotate(45deg);color:var(--acid);font:800 20px 'Barlow Condensed'}.crest:after{content:'IF';transform:rotate(-45deg)}.crest{font-size:0}h1{font:900 48px/.76 'Barlow Condensed';letter-spacing:2px;margin:18px 0;color:#f0f0e9}h1 em{font-style:normal;color:var(--acid)}.modal p{max-width:330px;margin:18px auto;color:#b4bab5;font-size:15px;line-height:1.35}.briefing{display:flex;text-align:left;border-top:1px solid #414845;border-bottom:1px solid #414845;padding:11px 0;margin:17px 0}.briefing>div{flex:1;padding-left:12px;border-left:1px solid #424846}.briefing>div:first-child{padding-left:0;border-left:0}.briefing small,.briefing b{display:block}.briefing small{font:700 9px 'Rajdhani';letter-spacing:2px;color:#9da59e}.briefing b{font:700 12px 'Rajdhani';letter-spacing:.7px;margin-top:4px}.primary-btn{width:100%;border:0;background:var(--acid);color:#171a16;padding:12px 16px;font:800 16px 'Barlow Condensed';letter-spacing:2px;cursor:pointer;clip-path:polygon(0 0,100% 0,100% 70%,96% 100%,0 100%);transition:.15s}.primary-btn:hover{background:#e5f564;transform:translateY(-1px)}.primary-btn span{float:right;font-size:20px;line-height:15px}.footnote{color:#858d88;font-size:10px;line-height:1.55;letter-spacing:.5px;margin-top:13px}.mobile-controls{display:none}.mobile-controls button{touch-action:none}.mobile-controls .stick{touch-action:none}.mobile-controls .stick i{touch-action:none}
@media(max-width:700px){.topline{height:60px;padding:11px 15px}.objective{font-size:9px;letter-spacing:1px}.brand{font-size:15px}.brand-mark{width:30px;height:30px}.hud{top:64px;left:12px;right:12px;min-width:0;gap:11px;padding:9px 10px}.wave-card{min-width:70px;grid-template-columns:34px 1fr}.wave-card>span:last-child{font-size:8px}.mission{min-width:70px;padding-left:9px}.mission strong{font-size:15px}.progress{width:32px}.health{min-width:72px;padding-left:9px}.health-line{width:39px}.ammo{padding-left:9px;min-width:85px}.ammo strong{font-size:21px}.ammo>span:last-child{font-size:7px}#map-wrap{top:133px;right:12px;width:95px;padding:5px}.map-label{font-size:8px}.bottom-hud{bottom:11px;left:12px;right:12px}.controls-hint{display:none}.player-tag{font-size:10px}.mobile-controls{display:block;position:absolute;inset:0;pointer-events:none}.stick{pointer-events:auto;position:absolute;left:20px;bottom:35px;width:112px;height:112px;border-radius:50%;background:#1016158a;border:1px solid #aeb8a966}.stick:before{content:'';position:absolute;inset:22px;border:1px solid #aeb8a944;border-radius:50%}.stick i{position:absolute;width:42px;height:42px;background:#bcc69a66;border:1px solid #d5e34d99;left:34px;top:34px;border-radius:50%}.touch-actions{pointer-events:auto;position:absolute;right:18px;bottom:25px;display:grid;grid-template-columns:48px 48px;gap:9px}.touch-actions button{height:44px;background:#101615bd;border:1px solid #aeb8a9;color:var(--acid);font:700 16px 'Rajdhani'}.touch-actions #touch-fire{grid-column:1/3;height:54px;background:#a33c2cbb;border-color:#e67b5e;color:#fff;letter-spacing:2px}.modal{padding:20px 24px}.crest{margin:12px auto 6px}h1{font-size:42px;margin:16px 0}.modal p{font-size:14px;margin:13px auto}.briefing{margin:12px 0;padding:9px 0}.briefing b{font-size:10px}.footnote{margin-top:9px}}
@media(max-height:500px){.modal{padding:12px 26px}.crest{display:none}h1{font-size:38px;margin:13px}.modal p{margin:9px auto}.briefing{margin:9px 0;padding:7px}.footnote{margin-top:7px}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d', { alpha: false });
  const mini = document.getElementById('minimap'), mctx = mini.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = { wave:$('wave'), state:$('wave-state'), left:$('enemies-left'), progress:$('wave-progress'), health:$('health-fill'), hp:$('health-value'), ammo:$('ammo'), reserve:$('reserve'), ammoStatus:$('ammo-status'), overlay:$('overlay'), title:$('overlay-title'), copy:$('overlay-copy'), start:$('start-btn'), toast:$('toast'), flash:$('damage-flash'), hit:$('hitmarker') };
  const GRID = 16, FOV = Math.PI / 3;
  // A compact siege arena: concrete perimeter, broken sightlines, and waist-high cover.
  const map = Array.from({length:GRID},(_,y)=>Array.from({length:GRID},(_,x)=>(x===0||y===0||x===GRID-1||y===GRID-1)?1:0));
  [[4,4,2],[5,4,2],[11,4,2],[11,5,2],[4,10,2],[4,11,2],[10,11,2],[11,11,2],[7,3,1],[8,3,1],[7,12,1],[8,12,1],[2,7,2],[2,8,2],[13,7,2],[13,8,2]].forEach(([x,y,t])=>map[y][x]=t);
  const player={x:8,y:8,angle:-Math.PI/2,hp:100,ammo:30,reserve:180,reloading:false,cover:false,alive:true,fireAt:0,lastHurt:0};
  let enemies=[],wave=0,spawned=0,totalWave=0,playing=false,between=0,last=0,toastTimer=0,hitTimer=0,flash=0,muzzle=0,shotKick=0,moveBob=0,score=0,eliminations=0;
  let W=0,H=0, keys={},mouseDown=false,dragLook=false,soundOn=false,audioCtx=null;
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const norm=a=>Math.atan2(Math.sin(a),Math.cos(a));
  const resize=()=>{const d=Math.min(devicePixelRatio||1,1.35);W=Math.max(360,Math.floor(innerWidth*d));H=Math.max(240,Math.floor(innerHeight*d));canvas.width=W;canvas.height=H;};
  addEventListener('resize',resize);resize();
  function solid(x,y){const gx=Math.floor(x),gy=Math.floor(y);return gx<0||gy<0||gx>=GRID||gy>=GRID||map[gy][gx]!==0;}
  function lineOfSight(x1,y1,x2,y2){const dx=x2-x1,dy=y2-y1,dist=Math.hypot(dx,dy),steps=Math.ceil(dist*12);for(let i=1;i<steps;i++){const t=i/steps;if(solid(x1+dx*t,y1+dy*t))return false;}return true;}
  function notify(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=1.6;}
  function blip(freq=120,dur=.07,type='square',vol=.035){if(!soundOn)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur);}catch(_){}}
  function spawnWave(){wave++;totalWave=4+wave*2;spawned=0;enemies=[];between=0;ui.wave.textContent=String(wave).padStart(2,'0');ui.state.textContent='OLEADA ACTIVA';notify(`OLEADA ${String(wave).padStart(2,'0')} — HOSTILES ENTRANDO`);}
  function spawnEnemy(){const candidates=[[1.5,1.5],[8,1.5],[14.5,1.5],[1.5,8],[14.5,8],[1.5,14.5],[8,14.5],[14.5,14.5],[5,1.5],[10.5,14.5]];let p=candidates[(Math.random()*candidates.length)|0];let tries=0;while((Math.hypot(p[0]-player.x,p[1]-player.y)<5||solid(p[0],p[1]))&&tries++<20)p=candidates[(Math.random()*candidates.length)|0];enemies.push({x:p[0]+(Math.random()-.5)*.6,y:p[1]+(Math.random()-.5)*.6,hp:wave>=4?3:2,speed:.48+Math.random()*.13,attack:Math.random()*.7,stun:0,walk:Math.random()*8});spawned++;}
  function startGame(){ui.overlay.classList.add('hidden');playing=true;player.x=8;player.y=8;player.angle=-Math.PI/2;player.hp=100;player.ammo=30;player.reserve=180;player.alive=true;player.cover=false;score=0;eliminations=0;wave=0;enemies=[];spawnWave();last=performance.now();if(innerWidth>700)canvas.requestPointerLock?.();}
  ui.start.addEventListener('click',()=>{if(!player.alive){startGame();return;}startGame();});
  canvas.addEventListener('click',()=>{if(playing&&document.pointerLockElement!==canvas&&innerWidth>700)canvas.requestPointerLock?.();});
  document.addEventListener('mousemove',e=>{if(playing&&document.pointerLockElement===canvas){player.angle+=e.movementX*.0023;}else if(playing&&dragLook){player.angle+=e.movementX*.006;}});
  document.addEventListener('pointerlockchange',()=>{dragLook=false;});
  canvas.addEventListener('pointerdown',e=>{if(e.button===0){mouseDown=true;if(playing&&document.pointerLockElement!==canvas)dragLook=true;}});
  addEventListener('pointerup',()=>{mouseDown=false;dragLook=false;});
  addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyR')reload();if(e.code==='KeyQ')toggleCover();if(e.code==='KeyE')resupply();if(e.code==='Escape'&&playing)dragLook=false;});
  addEventListener('keyup',e=>keys[e.code]=false);
  $('sound-btn').addEventListener('click',()=>{soundOn=!soundOn;$('sound-btn').style.color=soundOn?'#d4e34d':'#89918e';if(soundOn)blip(500,.08,'sine');});
  function reload(){if(!playing||player.reloading||player.ammo>=30||player.reserve<=0)return;player.reloading=true;ui.ammoStatus.textContent='RECARGANDO…';blip(220,.11,'triangle');setTimeout(()=>{if(!playing)return;const n=Math.min(30-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n;player.reloading=false;notify('RECARGA COMPLETA');},1050);}
  function toggleCover(){if(!playing)return;player.cover=!player.cover;notify(player.cover?'COBERTURA BAJA — DAÑO REDUCIDO':'FUERA DE COBERTURA');blip(player.cover?260:340,.06,'triangle');}
  function resupply(){if(!playing)return;player.reserve=Math.min(240,player.reserve+60);player.hp=Math.min(100,player.hp+20);notify('SUMINISTROS +60 · INTEGRIDAD +20');blip(520,.1,'sine');}
  function shoot(){if(!playing||player.reloading||!player.alive||performance.now()<player.fireAt)return;if(player.ammo<=0){ui.ammoStatus.textContent='SIN MUNICIÓN — R PARA RECARGAR';blip(95,.05);player.fireAt=performance.now()+240;return;}player.fireAt=performance.now()+145;player.ammo--;muzzle=.09;shotKick=1;blip(90,.08,'sawtooth',.022);let target=null,best=.095;for(const e of enemies){const d=Math.hypot(e.x-player.x,e.y-player.y),a=Math.abs(norm(Math.atan2(e.y-player.y,e.x-player.x)-player.angle));if(d<10&&a<best&&lineOfSight(player.x,player.y,e.x,e.y)){best=a;target=e;}}if(target){target.hp--;target.stun=.18;ui.hit.style.opacity='1';ui.hit.style.transform='translate(-50%,-50%) scale(1)';hitTimer=.16;if(target.hp<=0){enemies.splice(enemies.indexOf(target),1);score+=100;eliminations++;blip(180,.1,'triangle');}}}
  function hurt(amount){if(!player.alive)return;player.hp=Math.max(0,player.hp-amount*(player.cover?.45:1));player.lastHurt=performance.now();flash=.35;blip(65,.12,'sawtooth',.025);if(player.hp<=0){player.alive=false;playing=false;document.exitPointerLock?.();ui.title.innerHTML='MISIÓN<br><em>FALLIDA</em>';ui.copy.textContent=`La posición ha caído en la oleada ${wave}. Eliminaste ${eliminations} hostiles. ¿Intentamos otra vez?`;ui.start.innerHTML='REINTENTAR <span>↻</span>';ui.overlay.classList.remove('hidden');}}
  function move(dt){let f=0,s=0;if(keys.KeyW||keys.ArrowUp)f++;if(keys.KeyS||keys.ArrowDown)f--;if(keys.KeyD)s++;if(keys.KeyA)s--;let stickX=touch.x,stickY=touch.y;f+=-stickY;s+=stickX;if(!f&&!s)return;const len=Math.hypot(f,s)||1;f/=len;s/=len;const sprint=keys.ShiftLeft||keys.ShiftRight;const speed=(player.cover?1.45:sprint?3.5:2.55)*dt;const dx=(Math.cos(player.angle)*f-Math.sin(player.angle)*s)*speed,dy=(Math.sin(player.angle)*f+Math.cos(player.angle)*s)*speed;const r=.22;if(!solid(player.x+dx+r*Math.sign(dx),player.y))player.x+=dx;if(!solid(player.x,player.y+dy+r*Math.sign(dy)))player.y+=dy;moveBob+=dt*(sprint?13:9);}
  function update(dt,now){if(!playing)return;move(dt);if(mouseDown||touch.firing||keys.Space)shoot();if(spawned<totalWave){between-=dt;if(between<=0){spawnEnemy();between=Math.max(.35,1.15-wave*.035);}}if(spawned>=totalWave&&enemies.length===0){ui.state.textContent='SECTOR DESPEJADO';if(!between)between=4;else{between-=dt;if(between<=0)spawnWave();}}for(const e of enemies){if(e.stun>0){e.stun-=dt;continue;}const dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy);e.walk+=dt*7;if(d>1.16){const step=e.speed*dt,ex=dx/d*step,ey=dy/d*step;if(!solid(e.x+ex,e.y))e.x+=ex;if(!solid(e.x,e.y+ey))e.y+=ey;}else{e.attack-=dt;if(e.attack<=0){hurt(7+Math.min(5,wave));e.attack=1.1+Math.random()*.65;}}}if(player.hp<100&&now-player.lastHurt>7000)player.hp=Math.min(100,player.hp+dt*2.7);ui.left.textContent=String(enemies.length+Math.max(0,totalWave-spawned)).padStart(2,'0');ui.progress.style.width=`${totalWave?((spawned-enemies.length)/totalWave)*100:0}%`;ui.health.style.width=`${player.hp}%`;ui.hp.textContent=Math.ceil(player.hp);ui.ammo.textContent=String(player.ammo).padStart(2,'0');ui.reserve.textContent=player.reserve;ui.ammoStatus.textContent=player.reloading?'RECARGANDO…':player.ammo<=5?'MUNICIÓN BAJA':'LISTO PARA DISPARAR';if(toastTimer>0&&(toastTimer-=dt)<=0)ui.toast.classList.remove('show');if(hitTimer>0&&(hitTimer-=dt)<=0)ui.hit.style.opacity='0';flash=Math.max(0,flash-dt*1.6);ui.flash.style.opacity=flash;muzzle=Math.max(0,muzzle-dt);shotKick=Math.max(0,shotKick-dt*5);}
  function raycast(angle){const rayX=Math.cos(angle),rayY=Math.sin(angle);let mapX=Math.floor(player.x),mapY=Math.floor(player.y);const deltaX=Math.abs(1/(rayX||1e-10)),deltaY=Math.abs(1/(rayY||1e-10));let stepX,stepY,sideX,sideY;if(rayX<0){stepX=-1;sideX=(player.x-mapX)*deltaX;}else{stepX=1;sideX=(mapX+1-player.x)*deltaX;}if(rayY<0){stepY=-1;sideY=(player.y-mapY)*deltaY;}else{stepY=1;sideY=(mapY+1-player.y)*deltaY;}let side=0,steps=0;while(steps++<40){if(sideX<sideY){sideX+=deltaX;mapX+=stepX;side=0;}else{sideY+=deltaY;mapY+=stepY;side=1;}if(mapX<0||mapY<0||mapX>=GRID||mapY>=GRID||map[mapY][mapX])break;}let dist=side===0?sideX-deltaX:sideY-deltaY;dist=Math.max(.01,dist*Math.cos(angle-player.angle));const type=map[clamp(mapY,0,GRID-1)][clamp(mapX,0,GRID-1)]||1;return{dist,type,side,wallX:side===0?player.y+dist*Math.sin(angle):player.x+dist*Math.cos(angle)};}
